updated as (
  update medication_catalogs mc
  set
    active_ingredient = s.active_ingredient,
    dosage_form = s.dosage_form,
    manufacturer = s.manufacturer,
    ingredients = s.ingredients,
    route = s.route,
    description = s.description,
    common_uses = s.common_uses,
    warnings = s.warnings,
    contraindications = s.contraindications,
    side_effects = s.side_effects,
    interaction_notes = s.interaction_notes,
    updated_at = now()
  from seed s
  where mc.name = s.name
    and coalesce(mc.strength, '') = coalesce(s.strength, '')
  returning mc.id
)
insert into medication_catalogs (
  name,
  active_ingredient,
  strength,
  dosage_form,
  manufacturer,
  ingredients,
  route,
  description,
  common_uses,
  warnings,
  contraindications,
  side_effects,
  interaction_notes
)
select
  s.name,
  s.active_ingredient,
  s.strength,
  s.dosage_form,
  s.manufacturer,
  s.ingredients,
  s.route,
  s.description,
  s.common_uses,
  s.warnings,
  s.contraindications,
  s.side_effects,
  s.interaction_notes
from seed s
where not exists (
  select 1
  from medication_catalogs mc
  where mc.name = s.name
    and coalesce(mc.strength, '') = coalesce(s.strength, '')
);